import React, { useEffect, useMemo, useState } from 'react';
import { api } from './api';
import { Calendar, dateFnsLocalizer } from 'react-big-calendar';
import { format, parse, startOfWeek, getDay } from 'date-fns';
import { enUS } from 'date-fns/locale';
import 'react-big-calendar/lib/css/react-big-calendar.css';

/* ─── constants ─────────────────────────────────────────────── */
const emptyForms = {
  letter:     { title: '', send_to: '', description: '' },
  lecture:    { title: '', course: '', date: '', time: '', venue: '', recurrence: 'None' },
  meeting:    { title: '', with_whom: '', date: '', time: '', location: '' },
  commitment: { title: '', description: '', due_date: '', status: 'Pending' },
  task:       { title: '', topic: '', audience: '', due_date: '', priority: 'Medium', status: 'To Do' },
};

const EVENT_COLORS = {
  lecture:    '#1a4f8a',
  meeting:    '#2475b0',
  commitment: '#6c3483',
  task:       '#1a7a48',
};

const EVENT_COLORS_RGB = {
  lecture:    '26, 79, 138',
  meeting:    '36, 117, 176',
  commitment: '108, 52, 131',
  task:       '26, 122, 72',
};

const FILTER_LABELS = {
  lecture:    'Lectures',
  meeting:    'Meetings',
  commitment: 'Commitments',
  task:       'Tasks',
};

const CALENDAR_FILTERS = ['lecture', 'meeting', 'commitment', 'task'];

const TABS = [
  { id: 'calendar',    label: 'Calendar'    },
  { id: 'letters',     label: 'Letters'     },
  { id: 'lectures',    label: 'Lectures'    },
  { id: 'meetings',    label: 'Meetings'    },
  { id: 'commitments', label: 'Commitments' },
  { id: 'tasks',       label: 'Tasks'       },

];

const locales = { 'en-US': enUS };
const localizer = dateFnsLocalizer({ format, parse, startOfWeek, getDay, locales });

/* ─── App ────────────────────────────────────────────────────── */
const fmtTs = (ts) => {
  if (!ts) return '';
  const d = new Date(ts);
  return `${d.toLocaleDateString('en-GB', { day:'2-digit', month:'short', year:'numeric' })} ${d.toLocaleTimeString('en-GB', { hour:'2-digit', minute:'2-digit' })}`;
};

function App() {
  const [data, setData] = useState({
    letters: [], lectures: [], meetings: [], commitments: [], tasks: [],
  });
  const [forms, setForms]           = useState(emptyForms);
  const [loading, setLoading]       = useState(true);
  const [activeTab, setActiveTab]   = useState('calendar');
  const [calendarView, setCalendarView] = useState('month');
  const [filters, setFilters]       = useState({ lecture: true, meeting: true, commitment: true, task: true });

  /* ── data loading ── */
  const loadAll = async () => {
    setLoading(true);
    try {
      const [letters, lectures, meetings, commitments, tasks] = await Promise.all([
        api.get('/letters'),
        api.get('/lectures'),
        api.get('/meetings'),
        api.get('/commitments'),
        api.get('/talks'),        // backend table stays "talks"
      ]);
      setData({
        letters: letters.data,
        lectures: lectures.data,
        meetings: meetings.data,
        commitments: commitments.data,
        tasks: tasks.data,
      });
    } catch (err) {
      console.error('Failed to load data', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadAll(); }, []);

  useEffect(() => {
    if (window.Notification && Notification.permission === 'default') {
      Notification.requestPermission().catch(() => null);
    }
  }, []);

  /* ── form helpers ── */
  const onInput = (section, field, value) =>
    setForms((prev) => ({ ...prev, [section]: { ...prev[section], [field]: value } }));

  const addRecord = async (section, endpoint) => {
    try {
      await api.post(endpoint, forms[section]);
      setForms((prev) => ({ ...prev, [section]: emptyForms[section] }));
      loadAll();
    } catch (err) { console.error(`Failed to add ${section}`, err); }
  };

  const deleteRecord = async (endpoint, id) => {
    try { await api.delete(`${endpoint}/${id}`); loadAll(); }
    catch (err) { console.error('Delete error', err); }
  };

  const letterAction = async (id, action, payload) => {
    try { await api.put(`/letters/${id}/${action}`, payload || {}); loadAll(); }
    catch (err) { console.error('Letter action error', err); }
  };

  const taskStatusAction = async (id, status) => {
    try { await api.patch(`/talks/${id}/status`, { status }); loadAll(); }
    catch (err) { console.error('Task status error', err); }
  };

  const commitmentStatusAction = async (id, status) => {
    try { await api.patch(`/commitments/${id}/status`, { status }); loadAll(); }
    catch (err) { console.error('Commitment status error', err); }
  };

  /* ── calendar events ── */
  const calendarEvents = useMemo(() => {
    const statusIcon = (s) =>
      s === 'Completed' || s === 'Done' ? '✓ ' : s === 'In Progress' ? '⏳ ' : '';

    const lec = filters.lecture
      ? data.lectures.filter((i) => i.date && i.time).flatMap((i) => {
          const durationMs = (i.duration || 60) * 60000;
          const recurrence = i.recurrence || 'None';
          const base = new Date(`${i.date}T${i.time}`);
          const horizon = new Date(base);
          horizon.setMonth(horizon.getMonth() + 4); // generate 4 months ahead

          const stepDays = recurrence === 'Weekly' ? 7
            : recurrence === 'Fortnightly' ? 14
            : recurrence === 'Monthly' ? null   // handled separately
            : 0;

          const occurrences = [];
          let cursor = new Date(base);
          let idx = 0;
          while (cursor <= horizon) {
            const start = new Date(cursor);
            const end   = new Date(start.getTime() + durationMs);
            occurrences.push({
              id: `lecture-${i.id}-${idx}`,
              title: `${i.title}${recurrence !== 'None' ? ' ↻' : ''}`,
              start, end, allDay: false, type: 'lecture',
            });
            if (stepDays === 0) break; // no recurrence — single event
            if (recurrence === 'Monthly') {
              cursor = new Date(cursor);
              cursor.setMonth(cursor.getMonth() + 1);
            } else {
              cursor = new Date(cursor.getTime() + stepDays * 86400000);
            }
            idx++;
          }
          return occurrences;
        }) : [];

    const meet = filters.meeting
      ? data.meetings.filter((i) => i.date && i.time).map((i) => {
          const start = new Date(`${i.date}T${i.time}`);
          const end   = new Date(start.getTime() + 60 * 60000);
          return { id: `meeting-${i.id}`, title: i.title, start, end, allDay: false, type: 'meeting' };
        }) : [];

    const com = filters.commitment
      ? data.commitments.filter((i) => i.due_date).map((i) => ({
          id: `commitment-${i.id}`,
          title: `${statusIcon(i.status)}${i.title}`,
          type: 'commitment', allDay: false, status: i.status,
          start: new Date(`${i.due_date}T09:00:00`), end: new Date(`${i.due_date}T10:00:00`),
        })) : [];

    const tsk = filters.task
      ? data.tasks.filter((i) => i.due_date).map((i) => ({
          id: `task-${i.id}`,
          title: `${statusIcon(i.status)}${i.title} [${i.priority}]`,
          type: 'task', allDay: false, status: i.status, priority: i.priority,
          start: new Date(`${i.due_date}T11:00:00`), end: new Date(`${i.due_date}T12:00:00`),
        })) : [];

    return [...lec, ...meet, ...com, ...tsk];
  }, [data.lectures, data.meetings, data.commitments, data.tasks, filters]);

  const filterCounts = useMemo(() => ({
    lecture: data.lectures.length,
    meeting: data.meetings.length,
    commitment: data.commitments.length,
    task: data.tasks.length,
  }), [data.lectures.length, data.meetings.length, data.commitments.length, data.tasks.length]);

  /* ─── render ─────────────────────────────────────────────────── */
  return (
    <div className="page">

      {/* ── header ── */}
      <header className="hero">
        <div className="hero-brand">
          <svg className="logo-svg" viewBox="0 0 60 70" width="46" height="46" aria-hidden="true">
            {/* Arrow pointing up */}
            <polygon points="18,23 30,2 42,23 35,23 35,52 25,52 25,23" fill="rgba(255,255,255,0.95)"/>
            {/* Large checkmark overlapping arrow */}
            <polyline points="4,47 19,65 30,48"
              fill="none" stroke="rgba(255,255,255,0.88)" strokeWidth="8.5"
              strokeLinecap="round" strokeLinejoin="round"/>
            {/* Small checkbox */}
            <rect x="0" y="55" width="16" height="16" rx="3.5"
              fill="none" stroke="rgba(255,255,255,0.65)" strokeWidth="2.4"/>
            <polyline points="3,63 7.5,68.5 15,58"
              fill="none" stroke="rgba(255,255,255,0.65)" strokeWidth="2.4"
              strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
          <h1>Next<span className="logo-up">Up</span></h1>
        </div>
      </header>

      {/* ── tab nav ── */}
      <nav className="tab-nav">
        {TABS.map((tab) => (
          <button
            key={tab.id}
            className={`tab-btn${activeTab === tab.id ? ' tab-active' : ''}`}
            onClick={() => setActiveTab(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </nav>

      {loading && <p className="loading">Loading records…</p>}

      {/* ══════════════════ CALENDAR TAB ══════════════════ */}
      {activeTab === 'calendar' && (
        <div className="tab-page">
          <h2 className="tab-title">Academic Calendar</h2>
          <div className="filter-bar" role="tablist" aria-label="Academic calendar filters">
            {CALENDAR_FILTERS.map((type) => (
              <button
                key={type}
                className={`filter-btn${filters[type] ? ' filter-on' : ' filter-off'}`}
                role="tab"
                aria-selected={filters[type]}
                style={{ '--tab-color': EVENT_COLORS[type], '--tab-color-rgb': EVENT_COLORS_RGB[type] }}
                onClick={() => setFilters((prev) => ({ ...prev, [type]: !prev[type] }))}
              >
                <span className={`filter-check${filters[type] ? ' on' : ''}`}>✓</span>
                <span>{FILTER_LABELS[type]}</span>
                <span className="filter-count">{filterCounts[type]}</span>
              </button>
            ))}
          </div>
          <div className="calendar-shell">
            <Calendar
              localizer={localizer}
              events={calendarEvents}
              startAccessor="start"
              endAccessor="end"
              views={['month', 'week', 'day']}
              view={calendarView}
              onView={setCalendarView}
              style={{ height: 580 }}
              eventPropGetter={(event) => {
                const base = EVENT_COLORS[event.type] || '#2d5da6';
                const done = event.status === 'Completed' || event.status === 'Done';
                const inProg = event.status === 'In Progress';
                return {
                  style: {
                    backgroundColor: done ? '#7a9e7a' : inProg ? '#e09a30' : base,
                    border: 'none',
                    borderRadius: '5px',
                    color: '#fff',
                    opacity: done ? 0.7 : 1,
                    textDecoration: done ? 'line-through' : 'none',
                  },
                };
              }}
            />
          </div>
        </div>
      )}

      {/* ══════════════════ LETTERS TAB ══════════════════ */}
      {activeTab === 'letters' && (
        <div className="tab-page">
          <h2 className="tab-title">Letters and Approvals</h2>
          <div className="form-row">
            <input placeholder="Letter title" value={forms.letter.title}
              onChange={(e) => onInput('letter', 'title', e.target.value)} />
            <input placeholder="Send to (person / office)" value={forms.letter.send_to}
              onChange={(e) => onInput('letter', 'send_to', e.target.value)} />
          </div>
          <textarea placeholder="Description" value={forms.letter.description}
            onChange={(e) => onInput('letter', 'description', e.target.value)} />
          <button onClick={() => addRecord('letter', '/letters')}>Save as Draft</button>

          {data.letters.length === 0 && (
            <li className="empty-state">No letters yet.</li>
          )}

          <table className="letter-table">
            <thead>
              <tr>
                <th>Letter Title</th>
                <th>Send To</th>
                <th>Description</th>
                <th>Status</th>
                <th>Timeline</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {data.letters.map((item) => (
                <tr key={item.id}>
                  <td className="lt-title">{item.title}</td>
                  <td>{item.send_to || <span className="muted">—</span>}</td>
                  <td className="lt-desc">{item.description || <span className="muted">—</span>}</td>
                  <td>
                    <span className={`status-badge status-${item.status.toLowerCase().replace(' ', '-')}`}>
                      {item.status}
                    </span>
                  </td>
                  <td className="lt-timeline">
                    <div className="ts-row">Drafted: <span>{fmtTs(item.created_at)}</span></div>
                    {item.sent_at    && <div className="ts-row">Sent: <span>{fmtTs(item.sent_at)}</span></div>}
                    {item.decided_at && <div className="ts-row">Decided: <span>{fmtTs(item.decided_at)}</span></div>}
                  </td>
                  <td className="lt-actions">
                    {item.status === 'Draft' && (
                      <button className="action-btn send-btn"
                        onClick={() => letterAction(item.id, 'send')}>Mark Sent</button>
                    )}
                    {item.status === 'Sent' && (<>
                      <button className="action-btn approve-btn"
                        onClick={() => letterAction(item.id, 'decide', { decision: 'Approved' })}>Approved</button>
                      <button className="action-btn reject-btn"
                        onClick={() => letterAction(item.id, 'decide', { decision: 'Rejected' })}>Rejected</button>
                    </>)}
                    <button className="mini"
                      onClick={() => deleteRecord('/letters', item.id)}>Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* ══════════════════ LECTURES TAB ══════════════════ */}
      {activeTab === 'lectures' && (
        <div className="tab-page">
          <h2 className="tab-title">Lecture Schedule</h2>
          <div className="form-row">
            <input placeholder="Lecture title" value={forms.lecture.title}
              onChange={(e) => onInput('lecture', 'title', e.target.value)} />
            <input placeholder="Course" value={forms.lecture.course}
              onChange={(e) => onInput('lecture', 'course', e.target.value)} />
          </div>
          <div className="form-row three">
            <input type="date" value={forms.lecture.date}
              onChange={(e) => onInput('lecture', 'date', e.target.value)} />
            <input type="time" value={forms.lecture.time}
              onChange={(e) => onInput('lecture', 'time', e.target.value)} />
            <input placeholder="Venue" value={forms.lecture.venue}
              onChange={(e) => onInput('lecture', 'venue', e.target.value)} />
          </div>
          <div className="form-row">
            <select value={forms.lecture.recurrence}
              onChange={(e) => onInput('lecture', 'recurrence', e.target.value)}>
              <option value="None">No Repeat</option>
              <option value="Weekly">Weekly</option>
              <option value="Fortnightly">Fortnightly</option>
              <option value="Monthly">Monthly</option>
            </select>
          </div>
          <button onClick={() => addRecord('lecture', '/lectures')}>Add Lecture</button>

          {data.lectures.length === 0 && <p className="empty-state">No lectures yet.</p>}

          <table className="letter-table">
            <thead>
              <tr>
                <th>Title</th>
                <th>Course</th>
                <th>Date &amp; Time</th>
                <th>Venue</th>
                <th>Repeat</th>
                <th>Added</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {data.lectures.map((item) => (
                <tr key={item.id}>
                  <td className="lt-title">{item.title}</td>
                  <td>{item.course || <span className="muted">—</span>}</td>
                  <td><strong>{item.date}</strong>{item.time && <span className="muted"> {item.time}</span>}</td>
                  <td>{item.venue || <span className="muted">—</span>}</td>
                  <td>{item.recurrence && item.recurrence !== 'None'
                    ? <span className="recurrence-badge">↻ {item.recurrence}</span>
                    : <span className="muted">—</span>}
                  </td>
                  <td className="lt-timeline"><div className="ts-row">Added: <span>{fmtTs(item.created_at)}</span></div></td>
                  <td className="lt-actions">
                    <button className="mini" onClick={() => deleteRecord('/lectures', item.id)}>Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* ══════════════════ MEETINGS TAB ══════════════════ */}
      {activeTab === 'meetings' && (
        <div className="tab-page">
          <h2 className="tab-title">Meeting Schedule</h2>
          <div className="form-row">
            <input placeholder="Meeting title" value={forms.meeting.title}
              onChange={(e) => onInput('meeting', 'title', e.target.value)} />
            <input placeholder="With whom" value={forms.meeting.with_whom}
              onChange={(e) => onInput('meeting', 'with_whom', e.target.value)} />
          </div>
          <div className="form-row three">
            <input type="date" value={forms.meeting.date}
              onChange={(e) => onInput('meeting', 'date', e.target.value)} />
            <input type="time" value={forms.meeting.time}
              onChange={(e) => onInput('meeting', 'time', e.target.value)} />
            <input placeholder="Location" value={forms.meeting.location}
              onChange={(e) => onInput('meeting', 'location', e.target.value)} />
          </div>
          <button onClick={() => addRecord('meeting', '/meetings')}>Add Meeting</button>

          {data.meetings.length === 0 && <p className="empty-state">No meetings yet.</p>}

          <table className="letter-table">
            <thead>
              <tr>
                <th>Title</th>
                <th>With</th>
                <th>Date &amp; Time</th>
                <th>Location</th>
                <th>Added</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {data.meetings.map((item) => (
                <tr key={item.id}>
                  <td className="lt-title">{item.title}</td>
                  <td>{item.with_whom || <span className="muted">—</span>}</td>
                  <td><strong>{item.date}</strong>{item.time && <span className="muted"> {item.time}</span>}</td>
                  <td>{item.location || <span className="muted">—</span>}</td>
                  <td className="lt-timeline"><div className="ts-row">Added: <span>{fmtTs(item.created_at)}</span></div></td>
                  <td className="lt-actions">
                    <button className="mini" onClick={() => deleteRecord('/meetings', item.id)}>Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* ══════════════════ COMMITMENTS TAB ══════════════════ */}
      {activeTab === 'commitments' && (
        <div className="tab-page">
          <h2 className="tab-title">Commitments Tracker</h2>
          <div className="form-row">
            <input placeholder="Commitment title" value={forms.commitment.title}
              onChange={(e) => onInput('commitment', 'title', e.target.value)} />
            <select value={forms.commitment.status}
              onChange={(e) => onInput('commitment', 'status', e.target.value)}>
              <option>Pending</option><option>In Progress</option><option>Completed</option>
            </select>
          </div>
          <div className="form-row">
            <input type="date" value={forms.commitment.due_date}
              onChange={(e) => onInput('commitment', 'due_date', e.target.value)} />
            <input placeholder="Description" value={forms.commitment.description}
              onChange={(e) => onInput('commitment', 'description', e.target.value)} />
          </div>
          <button onClick={() => addRecord('commitment', '/commitments')}>Add Commitment</button>

          {data.commitments.length === 0 && <p className="empty-state">No commitments yet.</p>}

          <table className="letter-table">
            <thead>
              <tr>
                <th>Title</th>
                <th>Status</th>
                <th>Due Date</th>
                <th>Description</th>
                <th>Added</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {data.commitments.map((item) => (
                <tr key={item.id}>
                  <td className="lt-title">{item.title}</td>
                  <td>
                    <span className={`status-badge status-${item.status.toLowerCase().replace(' ', '-')}`}>{item.status}</span>
                  </td>
                  <td>{item.due_date || <span className="muted">—</span>}</td>
                  <td className="lt-desc">{item.description || <span className="muted">—</span>}</td>
                  <td className="lt-timeline"><div className="ts-row">Added: <span>{fmtTs(item.created_at)}</span></div></td>
                  <td className="lt-actions">
                    {item.status === 'Pending' && (
                      <button className="action-btn send-btn"
                        onClick={() => commitmentStatusAction(item.id, 'In Progress')}>Start</button>
                    )}
                    {item.status === 'In Progress' && (
                      <button className="action-btn approve-btn"
                        onClick={() => commitmentStatusAction(item.id, 'Completed')}>Complete</button>
                    )}
                    {item.status === 'Completed' && (
                      <button className="action-btn"
                        style={{ background: '#e8f0fe', color: '#1a4aaa' }}
                        onClick={() => commitmentStatusAction(item.id, 'Pending')}>Reopen</button>
                    )}
                    <button className="mini" onClick={() => deleteRecord('/commitments', item.id)}>Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* ══════════════════ TASKS TAB ══════════════════ */}
      {activeTab === 'tasks' && (
        <div className="tab-page">
          <h2 className="tab-title">Tasks with Priority</h2>
          <div className="form-row three">
            <input placeholder="Task title" value={forms.task.title}
              onChange={(e) => onInput('task', 'title', e.target.value)} />
            <input placeholder="Topic" value={forms.task.topic}
              onChange={(e) => onInput('task', 'topic', e.target.value)} />
            <input placeholder="Audience" value={forms.task.audience}
              onChange={(e) => onInput('task', 'audience', e.target.value)} />
          </div>
          <div className="form-row three">
            <input type="date" value={forms.task.due_date}
              onChange={(e) => onInput('task', 'due_date', e.target.value)} />
            <select value={forms.task.priority}
              onChange={(e) => onInput('task', 'priority', e.target.value)}>
              <option>High</option><option>Medium</option><option>Low</option>
            </select>
            <select value={forms.task.status}
              onChange={(e) => onInput('task', 'status', e.target.value)}>
              <option>To Do</option><option>In Progress</option><option>Done</option>
            </select>
          </div>
          <button onClick={() => addRecord('task', '/talks')}>Add Task</button>

          {data.tasks.length === 0 && <p className="empty-state">No tasks yet.</p>}

          <table className="letter-table">
            <thead>
              <tr>
                <th>Title</th>
                <th>Topic / Audience</th>
                <th>Priority</th>
                <th>Status</th>
                <th>Due Date</th>
                <th>Added</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {data.tasks.map((item) => (
                <tr key={item.id}>
                  <td className="lt-title">{item.title}</td>
                  <td className="lt-desc">
                    {item.topic && <div>{item.topic}</div>}
                    {item.audience && <div className="muted">{item.audience}</div>}
                    {!item.topic && !item.audience && <span className="muted">—</span>}
                  </td>
                  <td>
                    <span className={`priority-badge prio-${item.priority.toLowerCase()}`}>{item.priority}</span>
                  </td>
                  <td>
                    <span className={`status-badge status-${item.status.toLowerCase().replace(' ', '-')}`}>{item.status}</span>
                  </td>
                  <td>{item.due_date || <span className="muted">—</span>}</td>
                  <td className="lt-timeline"><div className="ts-row">Added: <span>{fmtTs(item.created_at)}</span></div></td>
                  <td className="lt-actions">
                    {item.status === 'To Do' && (
                      <button className="action-btn send-btn"
                        onClick={() => taskStatusAction(item.id, 'In Progress')}>Start</button>
                    )}
                    {item.status === 'In Progress' && (
                      <button className="action-btn approve-btn"
                        onClick={() => taskStatusAction(item.id, 'Done')}>Done</button>
                    )}
                    {item.status === 'Done' && (
                      <button className="action-btn"
                        style={{ background: '#e8f0fe', color: '#1a4aaa' }}
                        onClick={() => taskStatusAction(item.id, 'To Do')}>Reopen</button>
                    )}
                    <button className="mini" onClick={() => deleteRecord('/talks', item.id)}>Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

    </div>
  );
}

export default App;
